<script setup>
import { computed, onMounted, ref } from 'vue'
import WorldMap from './components/WorldMap.vue'
const page=ref('overview'),loading=ref(false),error=ref(''),events=ref([]),selectedCountry=ref(null),modal=ref(false)
const filters=ref({start:'2024-01-01T00:00',end:'2024-01-07T23:59',magnitude:'5'})
const largest=computed(()=>events.value.reduce((m,e)=>Math.max(m,e.magnitude??0),0))
async function load(bounds=null){loading.value=true;error.value='';try{const p=new URLSearchParams({start:new Date(filters.value.start).toISOString(),end:new Date(filters.value.end).toISOString(),min_magnitude:filters.value.magnitude,limit:'40'});if(bounds)Object.entries(bounds).forEach(([k,v])=>p.set(k.replace(/[A-Z]/g,l=>`_${l.toLowerCase()}`),v));const r=await fetch(`/api/v1/events?${p}`),d=await r.json();if(!r.ok)throw new Error(d.detail||'Каталог временно недоступен');events.value=d.items}catch(e){error.value=e.message;events.value=[]}finally{loading.value=false}}
async function choose(c){selectedCountry.value=c;modal.value=true;await load(c.bounds)}
onMounted(load)
</script>
<template>
<main><header><button class="brand" @click="page='overview'">SEISMO<span>SCOPE</span></button><p>Каталог сейсмических событий · USGS FDSN Event API</p><small>● данные через API</small></header>
<section v-if="page==='overview'" class="layout"><aside><em>РЕЖИМ НАБЛЮДЕНИЯ</em><h1>Сейсмическая<br>картина мира</h1><p>Укажите период и магнитуду. Нажмите на страну, чтобы увидеть сводку событий.</p><hr><b>Как читать карту</b><p class="minor">Терракотовые точки — эпицентры. Размер точки соответствует магнитуде.</p></aside><section class="content"><form @submit.prevent="load(selectedCountry?.bounds)"><label>Начало<input v-model="filters.start" type="datetime-local"></label><label>Конец<input v-model="filters.end" type="datetime-local"></label><label>Магнитуда от<input v-model="filters.magnitude" type="number" min="0" max="10" step=".1"></label><button :disabled="loading">{{loading?'Загрузка…':'Обновить карту'}}</button></form><p v-if="error" class="error">{{error}}</p><div class="heading"><div><em>ИНТЕРАКТИВНАЯ КАРТА</em><h2>Эпицентры и страны</h2></div><dl><div><dt>Событий</dt><dd>{{events.length}}</dd></div><div><dt>Макс.</dt><dd>{{largest?`M ${largest.toFixed(1)}`:'—'}}</dd></div></dl></div><WorldMap :events="events" :active-country-id="selectedCountry?.id" @select-country="choose"/><p class="note">Кликните по стране, чтобы открыть краткую сейсмическую сводку.</p></section></section>
<section v-else class="detail"><button class="back" @click="page='overview'">← К карте</button><em>СТРАНОВАЯ СВОДКА</em><h1>{{selectedCountry?.name}}</h1><p>События магнитудой от {{filters.magnitude}} за выбранный период.</p><div class="stats"><div><span>Найдено</span><strong>{{events.length}}</strong><small>событий</small></div><div><span>Максимум</span><strong>{{largest?`M ${largest.toFixed(1)}`:'—'}}</strong><small>за период</small></div><div><span>Источник</span><strong>USGS</strong><small>FDSN Event API</small></div></div><h2>События</h2><div v-if="!events.length" class="empty">Для выбранных параметров событий не найдено.</div><article v-for="e in events" :key="e.id"><b>M {{e.magnitude?.toFixed(1)??'—'}}</b><span>{{e.place}}<small>{{new Date(e.time).toLocaleString('ru-RU',{timeZone:'UTC'})}}</small></span><i>{{e.depth_km??'—'}} км</i></article></section>
<div v-if="modal" class="veil" @click.self="modal=false"><section class="modal" role="dialog" aria-modal="true"><button class="x" @click="modal=false" aria-label="Закрыть">×</button><em>СТРАНА ВЫБРАНА</em><h2>{{selectedCountry?.name}}</h2><p>Сводка событий в границах страны.</p><div class="modalstats"><span>Событий<strong>{{loading?'…':events.length}}</strong></span><span>Максимум<strong>{{loading?'…':(largest?`M ${largest.toFixed(1)}`:'—')}}</strong></span></div><button class="more" :disabled="loading" @click="modal=false;page='detail'">Подробнее о стране →</button></section></div>
</main>
</template>
